#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct { int u, v, w; } Edge;

static int *parent = NULL;
static int find_set(int x) {
    int p = parent[x];
    if (p != x) parent[x] = find_set(p);
    return parent[x];
}
static void union_set(int a, int b) {
    int ra = find_set(a), rb = find_set(b);
    if (ra != rb) parent[ra] = rb;
}

int main(int argc, char **argv) {
    if (argc < 2) { puts("INVALID_ARGS"); return 0; }
    char *endptr; long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || n < 0 || n > INT_MAX) { puts("INVALID_ARGS"); return 0; }
    Edge *edges = malloc(sizeof(Edge) * (size_t)n);
    if (!edges) { perror("malloc"); return 1; }
    int maxv = -1;
    for (long i = 0; i < n; ++i) {
        if (scanf("%d %d %d", &edges[i].u, &edges[i].v, &edges[i].w) != 3) { free(edges); puts("DISCONNECTED"); return 0; }
        if (edges[i].u > maxv) maxv = edges[i].u;
        if (edges[i].v > maxv) maxv = edges[i].v;
    }
    // insertion sort by weight
    for (size_t i = 1; i < (size_t)n; ++i) {
        Edge key = edges[i];
        ssize_t j = (ssize_t)i - 1;
        while (j >= 0 && edges[j].w > key.w) { edges[j+1] = edges[j]; --j; }
        edges[j+1] = key;
    }
    int vertex_cnt = maxv + 1;
    if (vertex_cnt < 0) vertex_cnt = 0;
    parent = calloc((size_t)vertex_cnt, sizeof(int));
    if (!parent) { perror("calloc"); free(edges); return 1; }
    for (int i = 0; i < vertex_cnt; ++i) parent[i] = i;
    Edge *mst = malloc(sizeof(Edge) * (size_t)n);
    if (!mst) { perror("malloc"); free(edges); free(parent); return 1; }
    int mst_cnt = 0; int total = 0;
    for (size_t i = 0; i < (size_t)n; ++i) {
        int ru = find_set(edges[i].u);
        int rv = find_set(edges[i].v);
        if (ru != rv) {
            union_set(ru, rv);
            mst[mst_cnt++] = edges[i];
            total += edges[i].w;
            if (mst_cnt == vertex_cnt - 1) break;
        }
    }
    if (mst_cnt < vertex_cnt - 1) {
        puts("DISCONNECTED");
    } else {
        printf("weight=%d edges=", total);
        for (int i = 0; i < mst_cnt; ++i) {
            if (i) putchar(',');
            printf("%d-%d", mst[i].u, mst[i].v);
        }
        putchar('\n');
    }
    free(edges); free(mst); free(parent);
    return 0;
}
